77	        LocalDate today = sheets.load(sheetId).getToday();
78	        RollupService.Snapshot before = rollup.snapshot(sheetId);
79	        String trimmed = name.strip();
80	        if (nameOrAliasInUse(sheetId, trimmed)) {
81	            throw nameInUse();
82	        }
83	        String key = contactKey(contact);
84	        if (key != null && people.existsBySheetIdAndContact(sheetId, key)) {
85	            throw contactInUse();
86	        }
87	        Person person = new Person(sheetId, trimmed, grade, today);
88	        person.setTerms(terms);
89	        person.setContact(key);
90	        Person added = save(person);
91	        audit.recordOnCommit(record("PERSON_ADDED", by, added, today(sheetId))
92	                + (terms != null ? " terms=" + terms : "")
93	                + (key != null ? " contact=" + key : ""));
94	        rollup.recordChanges(by, sheetId, before);
95	        return added;
96	    }
97	
98	    /**
99	     * Saves an edit made from the given version of the person; refused when it has been saved since. The grade is
100	     * recorded from the from-date (missing: the sheet's today), keeping the ones already recorded, except that an
101	     * edit leaving the grade in force today as it is, with no from-date, records nothing. The person's own terms are
102	     * set to the given ones (null: none), and their contact to the given one (blank or null: none), refused when
103	     * another person on the sheet has it.
104	     */
105	    @Transactional
106	    public Person update(String by, String sheetId, Long id, long version, String name, String grade,
107	            LocalDate gradeFrom, Integer terms, String contact) {
108	        return update(by, sheetId, id, version, name, grade, gradeFrom, terms, contact, true);
109	    }
110	
111	    /**
112	     * Saves the edit as {@link #update(String, String, Long, long, String, String, LocalDate, Integer, String)} does;
113	     * when checking the tree, refused too when the name, or any alias the person keeps, is a name or alias on another
114	     * sheet of the sheet's tree.
115	     */
116	    private Person update(String by, String sheetId, Long id, long version, String name, String grade,
117	            LocalDate gradeFrom, Integer terms, String contact, boolean checkTree) {
118	        LocalDate today = today(sheetId);
119	        RollupService.Snapshot before = rollup.snapshot(sheetId);
120	        Person person = people.findByIdAndSheetId(id, sheetId)
121	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
122	        if (person.getVersion() != version) {
123	            throw stale();
124	        }
125	        String trimmed = name.strip();
126	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)
127	                || people.findBySheetIdAndAlias(sheetId, trimmed).isPresent()) {
128	            throw nameInUse();
129	        }
130	        if (checkTree) {
131	            Set<String> tree = tree(sheetId);
132	            if (inUseOn(tree, trimmed) || person.getAliases().stream().anyMatch(a -> inUseOn(tree, a))) {
133	                throw nameInUse();
134	            }
135	        }
136	        String key = contactKey(contact);
137	        if (key != null && people.existsBySheetIdAndContactAndIdNot(sheetId, key, id)) {
138	            throw contactInUse();
139	        }
140	        person.setName(trimmed);
141	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
142	            person.recordGrade(grade, gradeFrom != null ? gradeFrom : today, today);
143	        }
144	        boolean termsChanged = !Objects.equals(terms, person.getTerms());
145	        person.setTerms(terms);
146	        boolean contactChanged = !Objects.equals(key, person.getContact());
147	        person.setContact(key);
148	        Person saved = save(person);
149	        audit.recordOnCommit(record("PERSON_EDITED", by, saved, today)
150	                + (termsChanged ? " terms=" + (terms != null ? terms : "") : "")
151	                + (contactChanged ? " contact=" + (key != null ? key : "") : ""));
152	        rollup.recordChanges(by, sheetId, before);
153	        return saved;
154	    }
155	
156	    /**
157	     * Gives each of the people a grade from the from-date (missing: the sheet's today), in list order, exactly as
158	     * saving each one's edit with that grade would, all or none: one that is not a person of the sheet refuses them
159	     * all. The people as saved, in list order.
160	     */
161	    @Transactional
162	    public List<Person> bulkGrade(String by, String sheetId, Set<Long> ids, String grade, LocalDate from) {
163	        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
164	                .filter(p -> ids.contains(p.getId())).toList();
165	        if (chosen.size() != ids.size()) {
166	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person.");
167	        }
168	        List<Person> saved = new ArrayList<>();
169	        for (Person p : chosen) {
170	            saved.add(update(by, sheetId, p.getId(), p.getVersion(), p.getName(), grade, from, p.getTerms(),
171	                    p.getContact(), false));
172	        }
173	        return saved;
174	    }
175	
176	    /** Retires the person from the date; a missing date takes the sheet's today. Their claims keep counting. */
177	    @Transactional
178	    public Person retire(String by, String sheetId, Long id, LocalDate from) {
179	        LocalDate today = sheets.load(sheetId).getToday();
180	        LocalDate on = from != null ? from : today;
181	        RollupService.Snapshot before = rollup.snapshot(sheetId);
182	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
183	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
184	        person.setRetiredFrom(on, today);
185	        Person saved = save(person);
186	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
187	                + " from=" + on);
188	        rollup.recordChanges(by, sheetId, before);
189	        return saved;
190	    }
191	
192	    /**
193	     * Puts a hold on the person from the date (missing: the sheet's today) to the to-date (missing: with no end); the
194	     * holds already put are kept, each ending on its to-date. Their open claims dated within a hold, not bound by a
195	     * statement, count in no live total. Refused when the to-date is before the from-date.
196	     */
197	    @Transactional
198	    public Person hold(String by, String sheetId, Long id, LocalDate from, LocalDate to) {
199	        LocalDate today = sheets.load(sheetId).getToday();
200	        LocalDate on = from != null ? from : today;
201	        if (to != null && to.isBefore(on)) {
202	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
203	        }
204	        RollupService.Snapshot before = rollup.snapshot(sheetId);
205	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
206	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
207	        person.addHold(on, to, today);
208	        Person saved = save(person);
209	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
210	                + " from=" + on);
211	        rollup.recordChanges(by, sheetId, before);
212	        return saved;
213	    }
214	
215	    /**
216	     * Gives the person the alias, without surrounding spaces; refused when blank, or when it equals, ignoring case,
217	     * any name or alias on the sheet or on another sheet of its tree.
218	     */
219	    @Transactional
220	    public Person addAlias(String by, String sheetId, Long id, String alias) {
221	        String trimmed = alias == null ? "" : alias.strip();
222	        if (trimmed.isEmpty()) {
223	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Enter an alias.");
224	        }
225	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
226	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
227	        if (nameOrAliasInUse(sheetId, trimmed)) {
228	            throw nameInUse();
229	        }
230	        person.addAlias(trimmed);
231	        Person saved = save(person);
232	        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
233	                + " alias=" + trimmed);
234	        return saved;
235	    }
236	
237	    @Transactional(readOnly = true)
238	    public List<Patron> patrons(String sheetId) {
239	        return patrons.findBySheetIdOrderByIdAsc(sheetId);
240	    }
241	
242	    /** Names another person on the sheet as the person's patron; never themselves, nor anyone twice. */
243	    @Transactional
244	    public Patron addPatron(String by, String sheetId, Long id, Long patronId) {
245	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
246	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
247	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
248	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
249	        if (person.getId().equals(patron.getId())) {
250	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A person cannot be their own patron.");
251	        }
252	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
253	            throw patronNamed();
254	        }
255	        Patron added;
256	        try {
257	            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
258	        } catch (DataIntegrityViolationException e) {
259	            throw patronNamed();
260	        }
261	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + by + " name=" + person.getName()
262	                + " patron=" + patron.getName());
263	        return added;
264	    }
265	
266	    /**
267	     * Whether the name or alias is, ignoring case, a name or an alias of anyone on the sheet or on another sheet of
268	     * its tree: its ancestors, and its descendants and theirs.
269	     */
270	    @Transactional(readOnly = true)
271	    public boolean nameOrAliasInUse(String sheetId, String nameOrAlias) {
272	        return people.nameOrAliasInUse(sheetId, nameOrAlias) || inUseOn(tree(sheetId), nameOrAlias);
273	    }
274	
275	    /**
276	     * The ids of the people on the sheet who clash: whose name or an alias is, ignoring case, a name or an alias on
277	     * another sheet of its tree (they came to clash before such names were refused, or as the tree was linked).
278	     */
279	    @Transactional(readOnly = true)
280	    public Set<Long> clashing(String sheetId) {
281	        Set<String> tree = tree(sheetId);
282	        if (tree.isEmpty()) {
283	            return Set.of();
284	        }
285	        Set<String> taken = new HashSet<>();
286	        for (Person p : people.findBySheetIdIn(tree)) {
287	            taken.add(p.getName().toLowerCase(Locale.ROOT));
288	            p.getAliases().forEach(a -> taken.add(a.toLowerCase(Locale.ROOT)));
289	        }
290	        Set<Long> clashing = new HashSet<>();
291	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
292	            if (taken.contains(p.getName().toLowerCase(Locale.ROOT))
293	                    || p.getAliases().stream().anyMatch(a -> taken.contains(a.toLowerCase(Locale.ROOT)))) {
294	                clashing.add(p.getId());
295	            }
296	        }
297	        return clashing;
298	    }
299	
300	    /**
301	     * The other sheets of the sheet's tree, among the sheets that exist: its parent, their parent and so on, and the
302	     * sheets naming it as parent, the ones naming those, and so on.
303	     */
304	    private Set<String> tree(String sheetId) {
305	        Set<String> tree = new LinkedHashSet<>();
306	        Set<String> seen = new HashSet<>(Set.of(sheetId));
307	        String at = sheetRepository.findById(sheetId).map(Sheet::getParentId).orElse(null);
308	        while (at != null && seen.add(at)) {
309	            Sheet parent = sheetRepository.findById(at).orElse(null);
310	            if (parent == null) {
311	                break;
312	            }
313	            tree.add(at);
314	            at = parent.getParentId();
315	        }
316	        ArrayDeque<String> toVisit = new ArrayDeque<>(List.of(sheetId));
317	        Set<String> below = new HashSet<>(Set.of(sheetId));
318	        while (!toVisit.isEmpty()) {
319	            for (Sheet child : sheetRepository.findByParentIdOrderByIdAsc(toVisit.poll())) {
320	                if (below.add(child.getId())) {
321	                    toVisit.add(child.getId());
322	                    if (!child.getId().equals(sheetId)) {
323	                        tree.add(child.getId());
324	                    }
325	                }
326	            }
327	        }
328	        tree.remove(sheetId);
329	        return tree;
330	    }
331	
332	    private boolean inUseOn(Set<String> sheetIds, String nameOrAlias) {
333	        return !sheetIds.isEmpty() && people.nameOrAliasInUseOn(sheetIds, nameOrAlias);
334	    }
335	
336	    /** A contact as stored: without surrounding spaces and lower-cased; null when blank. */
337	    private static String contactKey(String contact) {
338	        if (contact == null || contact.isBlank()) {
339	            return null;
340	        }
341	        return contact.strip().toLowerCase(Locale.ROOT);
342	    }
343	
344	    /** Saves the person; the store's unique indexes refuse a name or contact another request took meanwhile. */
345	    private Person save(Person person) {
346	        try {
347	            return people.saveAndFlush(person);
348	        } catch (DataIntegrityViolationException e) {
349	            throw nameOrContactInUse();
350	        } catch (ObjectOptimisticLockingFailureException e) {
351	            // another request saved the person between this one reading and writing it
352	            throw stale();
353	        }
354	    }
355	
356	    /** The audit line about a person, with the grade in force on the sheet's today. */
357	    private static String record(String event, String by, Person p, LocalDate today) {
358	        return event + " sheet=" + p.getSheetId() + " by=" + by + " name=" + p.getName() + " grade="
359	                + p.gradeOn(today);
360	    }
361	
362	    private static ResponseStatusException stale() {
363	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
364	                "Someone else has saved this person since it was opened.");
365	    }
366	
367	    private static ResponseStatusException patronNamed() {
368	        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already one of their patrons.");
369	    }
370	
371	    private static ResponseStatusException contactInUse() {
372	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on this sheet.");
373	    }
374	
375	    private static ResponseStatusException nameOrContactInUse() {
376	        return new ResponseStatusException(HttpStatus.CONFLICT,
377	                "That name or contact is already in use on this sheet.");
378	    }
379	
380	    private static ResponseStatusException nameInUse() {
381	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
382	    }
383	}
